using (TestHost host = TestHost.Start("1.7.3"))
{
    ModMain mod = host.Load<ModMain>("com.example.demo", "1.0.0");
    Assert.NotNull(mod);
    Assert.Equal(1, host.PressHotkey("F8"));
    host.Publish(Topics.Round, 3);
    host.Tick(1.0);
    Assert.DoesNotContain(host.Logs(), l => l.Lvl == "error");
}
